const sectionShrinkFloorKey = "section_shrink_floor"
const defaultSectionShrinkFloor = 0.5
const minShrinkGuardChars = 500

func evaluateSectionShrink(floor float64, existing map[string]int, incoming map[string]int) []slotShrink {
	if floor <= 0 { return nil }
	if floor > 0.95 { floor = 0.95 }
	for slot, existingLen := range existing {
		if existingLen < minShrinkGuardChars { continue }
		incomingLen, present := incoming[slot]
		if !present { continue } // a drop, not a shrink — the completeness floor's case
		if float64(incomingLen) < float64(existingLen)*floor { violations = append(...) }
	}
	return violations
}

